'use strict';
const http=require('node:http'),fs=require('node:fs'),{functionSource}=require('../helpers/app-functions.cjs'),{createBackend}=require('../helpers/labor-ui-flow.cjs'),P=require('../../js/core/permission-index'),{createAdminExpenseCreate}=require('../../cotizador/admin-expense-create'),{createAdminExpenseEdit}=require('../../cotizador/admin-expense-edit');
async function start({role='administrativo'}={}){
 const backend=createBackend({ventas:{},gastos:{},ctaemp:{e:{private:{tipo:'sueldo',monto:99999}}},sentinel:{stock:37,commission:50}});backend.state.sv_chat_roles.u={activo:true,rol:role,nombre:'Persona ficticia'};backend.state.sv_permisos=P.build({[role]:{bloqueados:['ctaemp'],acciones:{gastos:{administrar:true,crear:true,editar:true,pagar:true},empleados:{verCuentas:false}}}});
 backend.store.readAsUser=async path=>{if(!/^sisventas\/gastos\/[^/]+$/.test(path))throw Object.assign(Error('Private read forbidden'),{statusCode:403});return backend.get(path);};
 const db={ref:path=>({get:async()=>({val:()=>backend.get(path)})})},create=createAdminExpenseCreate({authorize:async()=>{},db,guard:backend.guard,enabled:true}),edit=createAdminExpenseEdit({authorize:async()=>{},store:backend.store,guard:backend.guard,enabled:true});
 const html='<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>body{background:#0b1424;color:#e7efff;font:16px system-ui;margin:20px}input,button{padding:12px;max-width:100%;box-sizing:border-box}form{display:grid;gap:10px;max-width:650px}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style><h1>Guardar y editar gasto</h1><p>Prueba aislada · datos ficticios</p><form><label>Descripción <input id="description" value="Accesorios ficticios"></label><label>Importe <input value="100,25" readonly></label><label>Pagado <input value="20,15" readonly></label><button type="button" id="create">Guardar gasto</button><button type="button" id="edit" disabled>Guardar edición</button><p id="result" role="status"></p></form><script>'+`window.currentUserUid='u';window.currentUser='Persona ficticia';window.currentRole=${JSON.stringify(role)};window.PERMISOS_ROLES=${JSON.stringify(backend.state.sv_permisos)};window.fbAuth={currentUser:{uid:'u'}};window.fbDB={};window.APP_CONFIG={READ_MODELS_REQUIRED:true};window.tienePermiso=()=>true;window.SISVENTAS_FUNCTIONS={cotizadorProveedor:location.origin};window.SVServiceAuth={headers:async h=>({...h,Authorization:'Bearer fixture-token'})};window.SVLaborWrites={atomic(){throw Error('Unexpected legacy fallback')}};window.SVLaborWriteRecovery={assertAvailable(){},execute:async(_,send,check)=>{check();return send();}};window.savedExpense=null;`+fs.readFileSync('js/core/financial-commands.js','utf8')+['_gastoEstaRetirado','_gastoBaseEdicion','_gastoEmpleadosVinculados','_guardarGastoCompletoAtomico'].map(functionSource).join('\n')+`
 async function submit(edit){const button=document.getElementById(edit?'edit':'create');button.disabled=true;button.textContent='Guardando…';try{const datos={fecha:'2026-11-03',tipo:'Variable',categoria:'Materiales',descripcion:document.getElementById('description').value,monto:100.25,montoPagado:20.15,estado:'pagado_parcial',medio:'Transferencia',empleadoId:'e',esFijoBase:false,fotoAdjunta:true,pagos:{p:{monto:20.15,fecha:'2026-10-31',medio:'Efectivo'}}};const result=await _guardarGastoCompletoAtomico(savedExpense,edit?savedExpense.fbKey:null,datos,'data:image/png;base64,QQ==');const response=await fetch('/expense?key='+result.key);savedExpense={...await response.json(),fbKey:result.key};document.getElementById('result').textContent=edit?'Edición guardada':'Gasto guardado';document.getElementById('edit').disabled=false;}catch(error){document.getElementById('result').textContent=error.message;}finally{button.disabled=false;button.textContent=edit?'Guardar edición':'Guardar gasto';}}
 document.getElementById('create').onclick=()=>submit(false);document.getElementById('edit').onclick=()=>submit(true);</script></html>`;
 const calls=[];const server=http.createServer(async(req,res)=>{const url=new URL(req.url,'http://localhost');res.setHeader('Cache-Control','no-store');
  if(req.method==='GET'&&url.pathname==='/'){res.setHeader('Content-Type','text/html;charset=utf-8');res.end(html);return;}
  if(req.method==='GET'&&url.pathname==='/expense'){const key=url.searchParams.get('key');if(!/^gasto_[a-f0-9]+$/.test(key||'')){res.writeHead(400).end();return;}res.setHeader('Content-Type','application/json');res.end(JSON.stringify(backend.get('sisventas/gastos/'+key)));return;}
  if(req.method==='POST'&&['/laboral/capacidades','/laboral/gastos/crear-administrativo','/laboral/gastos/editar-administrativo'].includes(url.pathname)){let text='';for await(const value of req){text+=value;if(text.length>1000000){res.writeHead(413).end();return;}}calls.push(url.pathname);try{const body=JSON.parse(text),actor={uid:'u',claims:{uid:'u'}},result=url.pathname.endsWith('/capacidades')?{ok:true,adminExpense:{enabled:true,version:1},payments:{enabled:true,version:1}}:url.pathname.endsWith('/crear-administrativo')?await create.create(actor,body):await edit.execute(actor,body);res.setHeader('Content-Type','application/json');res.end(JSON.stringify(result));}catch(error){res.writeHead(error.statusCode||503,{'Content-Type':'application/json'}).end(JSON.stringify({ok:false,code:error.code,mensaje:error.message}));}return;}
  res.writeHead(404).end();
 });await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));return{backend,calls,server,url:'http://127.0.0.1:'+server.address().port};
}
module.exports={start};
